const TRK={},SRC={},WANT={};
window.initA=function(){if(window.AC)return;AC=new(window.AudioContext||window.webkitAudioContext)();mg=AC.createGain();mg.gain.value=1;mg.connect(AC.destination)};
async function trk(k){if(TRK[k])return TRK[k];const b=atob(AUD[k].split(',')[1]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);TRK[k]=await new Promise((ok,no)=>AC.decodeAudioData(u.buffer,ok,no));return TRK[k]}
function fade(k,on,vol){WANT[k]=on;if(on){trk(k).then(buf=>{if(!WANT[k])return;let o=SRC[k];if(!o){const s=AC.createBufferSource();s.buffer=buf;s.loop=true;const g=AC.createGain();g.gain.value=0;s.connect(g);g.connect(mg);s.start(0);o=SRC[k]={s,g}}o.g.gain.cancelScheduledValues(AC.currentTime);o.g.gain.setTargetAtTime(vol,AC.currentTime,.9)}).catch(()=>{})}
else{const o=SRC[k];if(o){delete SRC[k];o.g.gain.cancelScheduledValues(AC.currentTime);o.g.gain.setTargetAtTime(0,AC.currentTime,.45);setTimeout(()=>{try{o.s.stop()}catch(e){}},2600)}}}
window.toggleMus=function(){initA();AC.resume();playing=!playing;const m=document.querySelector('#mus');m.classList.toggle('off',!playing);document.querySelector('#mt').textContent=playing?'MUSIK ON':'MUSIK OFF';fade('site',playing,.55)};
window.ivMusic=function(on){initA();AC.resume();ivOn=on;fade('wed',!!on,.6)};
window.sfx=function(f){if(!window.AC||!playing)return;const t=AC.currentTime,o=AC.createOscillator(),g=AC.createGain(),fl=AC.createBiquadFilter();o.type='sine';o.frequency.setValueAtTime(f*1.5,t);o.frequency.exponentialRampToValueAtTime(f,t+.09);fl.type='lowpass';fl.frequency.value=1600;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.045,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+.26);o.connect(fl);fl.connect(g);g.connect(mg);o.start(t);o.stop(t+.3)};
window.chime=function(){try{if(!window.AC)initA();AC.resume();const t=AC.currentTime;[[880,0],[1318.5,.11]].forEach(([f,d])=>{const o=AC.createOscillator(),g=AC.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t+d);g.gain.linearRampToValueAtTime(.06,t+d+.01);g.gain.exponentialRampToValueAtTime(.0001,t+d+.7);o.connect(g);g.connect(AC.destination);o.start(t+d);o.stop(t+d+.8)})}catch(e){}};

