window.pxCsv=(name,cols,rows)=>{const t=[cols.join(',')].concat(rows.map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(','))).join('\n');try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download=name;a.click()}catch(e){}tt('Laporan CSV diunduh: '+name)};

